contract RaffleFuzzTest is Test {
    uint256 internal constant ENTRY_PRICE = 1e6;

    address internal sponsor = makeAddr("fuzz-sponsor");
    address internal buyer = makeAddr("fuzz-buyer");
    address internal recipient = makeAddr("fuzz-recipient");
    address internal treasury = makeAddr("fuzz-treasury");
    address internal requester = makeAddr("fuzz-requester");

    MockERC20 internal quote;
    MockERC721 internal prize;
    MockVRFV2PlusWrapper internal vrfWrapper;
    RaffleFactory internal factory;
    uint256 internal nextPrizeId = 1;

    function setUp() public {
        vm.warp(10_000);
        quote = new MockERC20();
        prize = new MockERC721();
        vrfWrapper = new MockVRFV2PlusWrapper();
        factory = new RaffleFactory(address(quote), address(vrfWrapper), treasury);
        vm.prank(sponsor);
        prize.setApprovalForAll(address(factory), true);
        vm.deal(requester, 100 ether);
    }

    function testFuzzPurchaseCreatesOneSequentialTicketWithExactRange(uint128 entrySeed) public {
        uint128 entries = uint128(bound(uint256(entrySeed), 1, type(uint96).max));
        Raffle raffle = _create(type(uint128).max);
        _fundAndApprove(raffle, uint256(entries) * ENTRY_PRICE);

        vm.prank(buyer);
        uint256 ticketId = raffle.buyEntries(recipient, entries);
        (uint128 firstEntry, uint128 lastEntry) = raffle.ticketRange(ticketId);

        assertEq(firstEntry, 1);
        assertEq(lastEntry, entries);
        assertEq(ticketId, 1);
        assertEq(raffle.totalEntries(), entries);
        assertEq(raffle.ticketCount(), 1);
        assertEq(raffle.balanceOf(recipient), 1);
        assertEq(raffle.grossSales(), uint256(entries) * ENTRY_PRICE);
        assertEq(raffle.accountedQuoteBalance(), raffle.grossSales());
    }

    function testFuzzSeparatePurchasesPartitionEntriesWithoutGaps(uint128 firstSeed, uint128 secondSeed) public {
        uint128 firstCount = uint128(bound(uint256(firstSeed), 1, type(uint64).max));
        uint128 secondCount = uint128(bound(uint256(secondSeed), 1, type(uint64).max));
        Raffle raffle = _create(type(uint128).max);
        _fundAndApprove(raffle, (uint256(firstCount) + secondCount) * ENTRY_PRICE);

        vm.startPrank(buyer);
        uint256 firstId = raffle.buyEntries(buyer, firstCount);
        uint256 secondId = raffle.buyEntries(buyer, secondCount);
        vm.stopPrank();

        assertEq(firstId, 1);
        assertEq(secondId, 2);
        (uint128 firstStart, uint128 firstEnd) = raffle.ticketRange(firstId);
        (uint128 secondStart, uint128 secondEnd) = raffle.ticketRange(secondId);
        assertEq(firstStart, 1);
        assertEq(firstEnd, firstCount);
        assertEq(secondStart, firstCount + 1);
        assertEq(secondEnd, firstCount + secondCount);
        assertEq(uint256(firstEnd) + 1, secondStart);
    }

    function testFuzzWinningEntryAlwaysUsesInclusiveSoldRange(uint96 countSeed, uint256 randomWord) public {
        uint128 entries = uint128(bound(uint256(countSeed), 1, type(uint64).max));
        Raffle raffle = _create(entries);
        _fundAndApprove(raffle, uint256(entries) * ENTRY_PRICE);
        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, entries);

        _resolve(raffle, randomWord);

        uint128 expected = uint128((randomWord % uint256(entries)) + 1);
        assertEq(raffle.winningEntry(), expected);
        (uint128 firstEntry, uint128 lastEntry) = raffle.ticketRange(receiptId);
        assertGe(expected, firstEntry);
        assertLe(expected, lastEntry);
    }

    function testFuzzOnlyContainingReceiptCanSettle(uint32 firstSeed, uint32 secondSeed, uint256 randomWord) public {
        uint128 firstCount = uint128(bound(uint256(firstSeed), 1, 1_000_000));
        uint128 secondCount = uint128(bound(uint256(secondSeed), 1, 1_000_000));
        uint128 total = firstCount + secondCount;
        Raffle raffle = _create(total);
        _fundAndApprove(raffle, uint256(total) * ENTRY_PRICE);

        vm.startPrank(buyer);
        uint256 firstId = raffle.buyEntries(buyer, firstCount);
        uint256 secondId = raffle.buyEntries(recipient, secondCount);
        vm.stopPrank();
        _resolve(raffle, randomWord);

        uint256 winningId = raffle.winningEntry() <= firstCount ? firstId : secondId;
        uint256 losingId = winningId == firstId ? secondId : firstId;
        address winner = winningId == firstId ? buyer : recipient;
        uint128 selectedEntry = raffle.winningEntry();
        vm.expectRevert(
            abi.encodeWithSelector(IRaffle.TicketDoesNotContainWinningEntry.selector, losingId, selectedEntry)
        );
        raffle.settleWinningTicket(losingId);

        raffle.settleWinningTicket(winningId);
        assertEq(raffle.winnerRecipient(), address(0));
        assertEq(raffle.ownerOf(winningId), winner);
        assertEq(prize.ownerOf(raffle.prizeTokenId()), address(raffle));
        vm.prank(winner);
        raffle.redeemWinningTicket(winningId);
        assertEq(prize.ownerOf(raffle.prizeTokenId()), winner);
    }

    function testFuzzReserveEqualityIsNftAndOneBelowIsCash(uint32 reserveSeed) public {
        uint128 reserve = uint128(bound(uint256(reserveSeed), 2, 1_000_000));

        Raffle below = _create(reserve);
        _fundAndApprove(below, uint256(reserve - 1) * ENTRY_PRICE);
        vm.prank(buyer);
        below.buyEntries(buyer, reserve - 1);
        _resolve(below, 0);
        assertEq(uint256(below.status()), uint256(IRaffle.Status.CashWon));

        Raffle equal = _create(reserve);
        _fundAndApprove(equal, uint256(reserve) * ENTRY_PRICE);
        vm.prank(buyer);
        equal.buyEntries(buyer, reserve);
        _resolve(equal, 0);
        assertEq(uint256(equal.status()), uint256(IRaffle.Status.NftWon));
    }

    function testFuzzCashSplitAlwaysConservesEightyFifteenFive(uint64 entrySeed) public {
        uint128 entries = uint128(bound(uint256(entrySeed), 1, type(uint32).max));
        Raffle raffle = _create(entries + 1);
        uint256 gross = uint256(entries) * ENTRY_PRICE;
        _fundAndApprove(raffle, gross);
        vm.prank(buyer);
        uint256 ticketId = raffle.buyEntries(buyer, entries);
        _resolve(raffle, 0);

        uint256 fee = gross * 500 / 10_000;
        uint256 distributable = gross - fee;
        uint256 winnerCash = gross * 8000 / 10_000;
        uint256 sponsorCash = distributable - winnerCash;
        assertEq(raffle.protocolFees(), 0);
        assertEq(raffle.sponsorProceeds(), 0);
        assertEq(raffle.accountedQuoteBalance(), gross);

        uint256 winnerBefore = quote.balanceOf(buyer);
        raffle.settleWinningTicket(ticketId);
        assertEq(quote.balanceOf(buyer) - winnerBefore, 0);
        assertEq(raffle.winnerProceeds(), winnerCash);
        assertEq(raffle.protocolFees(), fee);
        assertEq(raffle.sponsorProceeds(), sponsorCash);
        assertEq(raffle.accountedQuoteBalance(), gross);

        vm.prank(buyer);
        raffle.redeemWinningTicket(ticketId);
        assertEq(quote.balanceOf(buyer) - winnerBefore, winnerCash);
        assertEq(raffle.winnerProceeds(), 0);
        assertEq(raffle.accountedQuoteBalance(), fee + sponsorCash);
    }

    function testFuzzRefundPaysWeightedRangeExactlyOnce(uint64 entrySeed) public {
        uint128 entries = uint128(bound(uint256(entrySeed), 1, type(uint32).max));
        Raffle raffle = _create(type(uint128).max);
        uint256 gross = uint256(entries) * ENTRY_PRICE;
        _fundAndApprove(raffle, gross);
        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, entries);
        vm.warp(raffle.endTime());
        vm.prank(requester);
        raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();
        vm.warp(raffle.callbackDeadline());
        raffle.enableRefunds();

        uint256 before = quote.balanceOf(buyer);
        vm.prank(buyer);
        assertEq(raffle.refundTickets(_single(receiptId)), gross);
        assertEq(quote.balanceOf(buyer) - before, gross);
        assertEq(raffle.remainingRefundLiability(), 0);
        vm.prank(buyer);
        vm.expectRevert();
        raffle.refundTickets(_single(receiptId));
    }

    function testFuzzNoRequestTimeoutPaysFullWeightedRange(uint64 entrySeed) public {
        uint128 entries = uint128(bound(uint256(entrySeed), 1, type(uint32).max));
        Raffle raffle = _create(type(uint128).max);
        uint256 gross = uint256(entries) * ENTRY_PRICE;
        _fundAndApprove(raffle, gross);
        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, entries);

        vm.warp(raffle.drawRequestDeadline());
        raffle.enableRefunds();
        assertEq(raffle.unsettledPot(), 0);
        assertEq(raffle.remainingRefundLiability(), gross);
        assertEq(raffle.accountedQuoteBalance(), gross);

        uint256 before = quote.balanceOf(buyer);
        vm.prank(buyer);
        assertEq(raffle.refundTickets(_single(receiptId)), gross);
        assertEq(quote.balanceOf(buyer) - before, gross);
        assertEq(raffle.remainingRefundLiability(), 0);
    }

    function testFuzzPostSettlementBearerCanRedeemNft(uint64 entrySeed) public {
        uint128 entries = uint128(bound(uint256(entrySeed), 1, type(uint32).max));
        Raffle raffle = _create(entries);
        _fundAndApprove(raffle, uint256(entries) * ENTRY_PRICE);
        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, entries);
        _resolve(raffle, 0);
        vm.prank(buyer);
        raffle.transferFrom(buyer, recipient, receiptId);
        vm.prank(requester);
        raffle.settleWinningTicket(receiptId);
        assertEq(raffle.winnerRecipient(), address(0));
        assertEq(raffle.ownerOf(receiptId), recipient);
        vm.prank(recipient);
        raffle.redeemWinningTicket(receiptId);
        assertEq(prize.ownerOf(raffle.prizeTokenId()), recipient);
    }

    function _create(uint128 reserveEntries) internal returns (Raffle raffle) {
        uint256 tokenId = nextPrizeId++;
        prize.mint(sponsor, tokenId);
        vm.prank(sponsor);
        raffle = Raffle(
            payable(factory.createRaffle(
                    IRaffleFactory.CreateRaffleParams({
                        sponsorRecipient: sponsor,
                        prizeToken: address(prize),
                        prizeTokenId: tokenId,
                        reserveEntries: reserveEntries,
                        endTime: uint64(block.timestamp + 1 days)
                    })
                ))
        );
    }

    function _fundAndApprove(Raffle raffle, uint256 amount) internal {
        quote.mint(buyer, amount);
        vm.prank(buyer);
        quote.approve(address(raffle), type(uint256).max);
    }

    function _resolve(Raffle raffle, uint256 randomWord) internal {
        vm.warp(raffle.endTime());
        vm.prank(requester);
        uint256 requestId = raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();
        vrfWrapper.fulfill(requestId, randomWord);
    }

    function _single(uint256 receiptId) internal pure returns (uint256[] memory ids) {
        ids = new uint256[](1);
        ids[0] = receiptId;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { IERC721Receiver } from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import { Test } from "forge-std/Test.sol";

import { Raffle } from "../../../src/Raffle.sol";
import { IRaffle } from "../../../src/interfaces/IRaffle.sol";
import { MockERC20 } from "../../../src/mocks/MockERC20.sol";
import { MockVRFV2PlusWrapper } from "../../../src/mocks/MockVRFV2PlusWrapper.sol";

contract RaffleHandler is Test, IERC721Receiver {
    uint128 internal constant MAX_HANDLER_ENTRIES = 100;

    MockERC20 public immutable quote;
    MockVRFV2PlusWrapper public immutable vrfWrapper;
    address public immutable treasury;
    address public immutable alternateOwner = address(0xA11CE);

    Raffle public raffle;
    uint256[] public receiptIds;
    uint256 public ghostGrossPaid;
    uint256 public ghostQuotePaidOut;
    uint256 public ghostRefundPaidOut;
    uint256 public ghostProtocolPaidOut;
    uint256 public ghostSponsorPaidOut;
    uint256 public ghostWinnerPaidOut;
    uint256 public ghostDonations;
    uint256 public ghostRequestCount;
    uint256 public ghostResolutionCount;
    uint256 public ghostRefundEnableCount;
    uint256 public ghostWinnerSettlements;
    uint256 public ghostWinnerRedemptions;
    bool public ghostCashResolved;
    bool public statusWentBackward;
    IRaffle.Status public highestStatus;

    constructor(MockERC20 quote_, MockVRFV2PlusWrapper vrfWrapper_, address treasury_) {
        quote = quote_;
        vrfWrapper = vrfWrapper_;
        treasury = treasury_;
    }

    function configure(Raffle raffle_) external {
        require(address(raffle) == address(0), "configured");
        raffle = raffle_;
        quote.approve(address(raffle_), type(uint256).max);
        vm.prank(alternateOwner);
        quote.approve(address(raffle_), type(uint256).max);
        highestStatus = raffle_.status();
    }

    function receiptIdAt(uint256 index) external view returns (uint256) {
        return receiptIds[index];
    }

    function receiptIdsLength() external view returns (uint256) {
        return receiptIds.length;
    }

    function buy(uint128 quantitySeed) external {
        if (raffle.status() != IRaffle.Status.Active || block.timestamp >= raffle.endTime()) return;
        uint128 sold = raffle.totalEntries();
        if (sold >= MAX_HANDLER_ENTRIES) return;
        uint128 remaining = MAX_HANDLER_ENTRIES - sold;
        uint128 quantity = uint128(bound(uint256(quantitySeed), 1, remaining < 10 ? remaining : 10));
        uint256 grossBefore = raffle.grossSales();
        try raffle.buyEntries(address(this), quantity) returns (uint256 receiptId) {
            receiptIds.push(receiptId);
            ghostGrossPaid += raffle.grossSales() - grossBefore;
        } catch { }
        _observe();
    }

    function transferBeforeOrAfterEnd(uint256 receiptSeed) external {
        if (receiptIds.length == 0) return;
        uint256 receiptId = receiptIds[receiptSeed % receiptIds.length];
        try raffle.ownerOf(receiptId) returns (address owner) {
            address to = owner == address(this) ? alternateOwner : address(this);
            vm.prank(owner);
            try raffle.transferFrom(owner, to, receiptId) { } catch { }
        } catch { }
        _observe();
    }

    function warpToEnd() external {
        if (block.timestamp < raffle.endTime()) vm.warp(raffle.endTime());
        _observe();
    }

    function warpToDrawRequestDeadline() external {
        uint256 deadline = raffle.drawRequestDeadline();
        if (block.timestamp < deadline) vm.warp(deadline);
        _observe();
    }

    function warpToLastDrawRequestSecond() external {
        uint256 deadline = raffle.drawRequestDeadline();
        if (block.timestamp < deadline - 1) vm.warp(deadline - 1);
        _observe();
    }

    function warpToCallbackDeadline() external {
        uint256 deadline = raffle.callbackDeadline();
        if (deadline != 0 && block.timestamp < deadline) vm.warp(deadline);
        _observe();
    }

    function warpFarPastEnd() external {
        uint256 farFuture = uint256(raffle.endTime()) + 365 days;
        if (block.timestamp < farFuture) vm.warp(farFuture);
        _observe();
    }

    function requestDraw() external {
        if (
            raffle.status() != IRaffle.Status.Active || raffle.totalEntries() == 0 || block.timestamp < raffle.endTime()
                || block.timestamp >= raffle.drawRequestDeadline()
        ) {
            return;
        }
        uint256 fee = raffle.getVrfRequestPrice();
        vm.deal(address(this), address(this).balance + fee);
        try raffle.requestDraw{ value: fee }() {
            ++ghostRequestCount;
        } catch { }
        _observe();
    }

    function fulfill(uint256 randomWord) external {
        if (raffle.status() != IRaffle.Status.Drawing) return;
        try vrfWrapper.fulfill(raffle.vrfRequestId(), randomWord) {
            IRaffle.Status result = raffle.status();
            if (result == IRaffle.Status.NftWon || result == IRaffle.Status.CashWon) {
                ++ghostResolutionCount;
                if (result == IRaffle.Status.CashWon) ghostCashResolved = true;
            }
        } catch { }
        _observe();
    }

    function wrongCallback(uint256 randomWord) external {
        if (raffle.status() != IRaffle.Status.Drawing) return;
        try vrfWrapper.fulfillAs(raffle.vrfRequestId(), raffle.vrfRequestId() + 1, randomWord) { } catch { }
        _observe();
    }

    function enableRefunds() external {
        IRaffle.Status current = raffle.status();
        bool ready = current == IRaffle.Status.Active && raffle.totalEntries() == 0;
        ready = ready
            || (current == IRaffle.Status.Active
                && raffle.totalEntries() != 0
                && block.timestamp >= raffle.drawRequestDeadline());
        ready = ready || (current == IRaffle.Status.Drawing && block.timestamp >= raffle.callbackDeadline());
        if (!ready) return;
        try raffle.enableRefunds() {
            ++ghostRefundEnableCount;
        } catch { }
        _observe();
    }

    function settleCandidateWinner(uint256 receiptSeed) external {
        IRaffle.Status current = raffle.status();
        if ((current != IRaffle.Status.NftWon && current != IRaffle.Status.CashWon) || receiptIds.length == 0) return;
        uint256 receiptId = receiptIds[receiptSeed % receiptIds.length];
        try raffle.settleWinningTicket(receiptId) returns (uint256) {
            ++ghostWinnerSettlements;
        } catch { }
        _observe();
    }

    function releaseWinnerClaim() external {
        IRaffle.Status current = raffle.status();
        if (
            (current != IRaffle.Status.CashWon && current != IRaffle.Status.NftWon) || !raffle.settlementComplete()
                || raffle.winnerRedeemed()
        ) return;

        uint256 ticketId = raffle.winningTicketId();
        address owner;
        try raffle.ownerOf(ticketId) returns (address owner_) {
            owner = owner_;
        } catch {
            return;
        }
        vm.prank(owner);
        try raffle.redeemWinningTicket(ticketId) returns (uint256 amount) {
            ++ghostWinnerRedemptions;
            ghostQuotePaidOut += amount;
            ghostWinnerPaidOut += amount;
        } catch { }
        _observe();
    }

    function redeemRefund(uint256 receiptSeed) external {
        if (raffle.status() != IRaffle.Status.Refunding || receiptIds.length == 0) return;
        uint256 receiptId = receiptIds[receiptSeed % receiptIds.length];
        address owner;
        try raffle.ownerOf(receiptId) returns (address owner_) {
            owner = owner_;
        } catch {
            return;
        }
        uint256[] memory ids = new uint256[](1);
        ids[0] = receiptId;
        vm.prank(owner);
        try raffle.refundTickets(ids) returns (uint256 amount) {
            ghostQuotePaidOut += amount;
            ghostRefundPaidOut += amount;
        } catch { }
        _observe();
    }

    function releaseProceeds(bool protocolClaim) external {
        uint256 expected = protocolClaim ? raffle.protocolFees() : raffle.sponsorProceeds();
        if (expected == 0) return;
        if (protocolClaim) {
            try raffle.releaseProtocolFees() returns (uint256 amount) {
                ghostQuotePaidOut += amount;
                ghostProtocolPaidOut += amount;
            } catch { }
        } else {
            try raffle.releaseSponsorProceeds() returns (uint256 amount) {
                ghostQuotePaidOut += amount;
                ghostSponsorPaidOut += amount;
            } catch { }
        }
        _observe();
    }

    function releaseSponsorPrize() external {
        IRaffle.Status current = raffle.status();
        if (raffle.prizeClaimed() || (current != IRaffle.Status.CashWon && current != IRaffle.Status.Refunding)) {
            return;
        }
        try raffle.releaseSponsorPrize() { } catch { }
        _observe();
    }

    function donate(uint64 amountSeed) external {
        uint256 amount = bound(uint256(amountSeed), 1, 10 * 1e6);
        quote.mint(address(raffle), amount);
        ghostDonations += amount;
        _observe();
    }

    function _observe() internal {
        IRaffle.Status current = raffle.status();
        if (uint256(current) < uint256(highestStatus)) statusWentBackward = true;
        if (uint256(current) > uint256(highestStatus)) highestStatus = current;
    }

    function onERC721Received(address, address, uint256, bytes calldata) external pure returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { StdInvariant } from "forge-std/StdInvariant.sol";
import { Test } from "forge-std/Test.sol";

import { Raffle } from "../../../src/Raffle.sol";
import { RaffleFactory } from "../../../src/RaffleFactory.sol";
import { IRaffle } from "../../../src/interfaces/IRaffle.sol";
import { IRaffleFactory } from "../../../src/interfaces/IRaffleFactory.sol";
import { MockERC20 } from "../../../src/mocks/MockERC20.sol";
import { MockERC721 } from "../../../src/mocks/MockERC721.sol";
import { MockVRFV2PlusWrapper } from "../../../src/mocks/MockVRFV2PlusWrapper.sol";
import { RaffleHandler } from "./RaffleHandler.sol";

contract RaffleInvariantTest is StdInvariant, Test {
    uint256 internal constant ENTRY_PRICE = 1e6;

    MockERC20 internal quote;
    MockERC721 internal prize;
    MockVRFV2PlusWrapper internal vrfWrapper;
    Raffle internal raffle;
    RaffleHandler internal handler;
    address internal treasury = makeAddr("invariant-treasury");

    function setUp() public {
        vm.warp(100_000);
        quote = new MockERC20();
        prize = new MockERC721();
        vrfWrapper = new MockVRFV2PlusWrapper();
        handler = new RaffleHandler(quote, vrfWrapper, treasury);
        RaffleFactory factory = new RaffleFactory(address(quote), address(vrfWrapper), treasury);

        prize.mint(address(handler), 1);
        vm.prank(address(handler));
        prize.setApprovalForAll(address(factory), true);
        vm.prank(address(handler));
        raffle = Raffle(
            payable(factory.createRaffle(
                    IRaffleFactory.CreateRaffleParams({
                        sponsorRecipient: address(handler),
                        prizeToken: address(prize),
                        prizeTokenId: 1,
                        reserveEntries: 50,
                        endTime: uint64(block.timestamp + 7 days)
                    })
                ))
        );
        quote.mint(address(handler), 1_000_000 * ENTRY_PRICE);
        quote.mint(handler.alternateOwner(), 1_000_000 * ENTRY_PRICE);
        handler.configure(raffle);

        bytes4[] memory selectors = new bytes4[](17);
        selectors[0] = handler.buy.selector;
        selectors[1] = handler.transferBeforeOrAfterEnd.selector;
        selectors[2] = handler.warpToEnd.selector;
        selectors[3] = handler.warpToDrawRequestDeadline.selector;
        selectors[4] = handler.warpToLastDrawRequestSecond.selector;
        selectors[5] = handler.warpToCallbackDeadline.selector;
        selectors[6] = handler.warpFarPastEnd.selector;
        selectors[7] = handler.requestDraw.selector;
        selectors[8] = handler.fulfill.selector;
        selectors[9] = handler.wrongCallback.selector;
        selectors[10] = handler.enableRefunds.selector;
        selectors[11] = handler.settleCandidateWinner.selector;
        selectors[12] = handler.redeemRefund.selector;
        selectors[13] = handler.releaseProceeds.selector;
        selectors[14] = handler.donate.selector;
        selectors[15] = handler.releaseSponsorPrize.selector;
        selectors[16] = handler.releaseWinnerClaim.selector;
        targetContract(address(handler));
        targetSelector(FuzzSelector({ addr: address(handler), selectors: selectors }));
    }

    function invariantStatusAndTerminalTransitionsAreMonotonic() public view {
        assertFalse(handler.statusWentBackward());
        assertLe(handler.ghostRequestCount(), 1);
        assertLe(handler.ghostResolutionCount(), 1);
        assertLe(handler.ghostRefundEnableCount(), 1);
        assertLe(handler.ghostWinnerSettlements(), 1);
        assertLe(handler.ghostWinnerRedemptions(), 1);
        if (handler.ghostCashResolved()) {
            assertNotEq(uint256(raffle.status()), uint256(IRaffle.Status.Refunding));
        }
    }

    function invariantRangesPartitionEverySoldEntryExactlyOnce() public view {
        uint256 expectedFirst = 1;
        uint256 length = handler.receiptIdsLength();
        for (uint256 index; index < length; ++index) {
            (uint128 firstEntry, uint128 lastEntry) = raffle.ticketRange(handler.receiptIdAt(index));
            assertEq(firstEntry, expectedFirst);
            assertGe(lastEntry, firstEntry);
            expectedFirst = uint256(lastEntry) + 1;
        }
        assertEq(expectedFirst - 1, raffle.totalEntries());
        assertEq(length, raffle.ticketCount());
        assertEq(raffle.grossSales(), uint256(raffle.totalEntries()) * ENTRY_PRICE);
    }

    function invariantWinningEntryHasExactlyOneReceiptProof() public view {
        if (raffle.winningEntry() == 0) return;
        assertGe(raffle.winningEntry(), 1);
        assertLe(raffle.winningEntry(), raffle.totalEntries());
        uint256 containingRanges;
        for (uint256 index; index < handler.receiptIdsLength(); ++index) {
            (uint128 firstEntry, uint128 lastEntry) = raffle.ticketRange(handler.receiptIdAt(index));
            if (raffle.winningEntry() >= firstEntry && raffle.winningEntry() <= lastEntry) ++containingRanges;
        }
        assertEq(containingRanges, 1);
    }

    function invariantTicketIdsAreSequential() public view {
        for (uint256 index; index < handler.receiptIdsLength(); ++index) {
            assertEq(handler.receiptIdAt(index), index + 1);
        }
    }

    function invariantDrawAndCallbackDeadlinesAreHardAndOrdered() public view {
        assertEq(raffle.drawRequestDeadline(), uint256(raffle.endTime()) + 2 days);
        uint256 requestedAt = raffle.drawRequestedAt();
        if (requestedAt != 0) {
            assertGe(requestedAt, raffle.endTime());
            assertLt(requestedAt, raffle.drawRequestDeadline());
            assertEq(raffle.callbackDeadline(), requestedAt + 2 days);
        }
        uint256 resolvedAt = raffle.resolvedAt();
        if (resolvedAt != 0) {
            assertGe(resolvedAt, requestedAt);
            assertLt(resolvedAt, raffle.callbackDeadline());
        }
    }

    function invariantQuoteAccountingIsExactAndSolvent() public view {
        assertEq(raffle.grossSales(), handler.ghostGrossPaid());
        assertEq(
            raffle.grossSales() + handler.ghostDonations(),
            quote.balanceOf(address(raffle)) + handler.ghostQuotePaidOut()
        );
        assertEq(
            raffle.accountedQuoteBalance(),
            raffle.unsettledPot() + raffle.remainingRefundLiability() + raffle.winnerProceeds()
                + raffle.sponsorProceeds() + raffle.protocolFees()
        );
        assertGe(quote.balanceOf(address(raffle)), raffle.accountedQuoteBalance());
    }

    function invariantBranchEconomicsRemainEightyFifteenFiveNinetyFiveFiveOrFullRefund() public view {
        IRaffle.Status current = raffle.status();
        uint256 fee = raffle.grossSales() * 500 / 10_000;
        if (current == IRaffle.Status.CashWon) {
            if (!raffle.settlementComplete()) {
                assertEq(raffle.unsettledPot(), raffle.grossSales());
                assertEq(raffle.sponsorProceeds(), 0);
                assertEq(raffle.protocolFees(), 0);
            } else {
                assertEq(raffle.unsettledPot(), 0);
                assertEq(raffle.winnerProceeds() + handler.ghostWinnerPaidOut(), raffle.grossSales() * 8000 / 10_000);
                assertEq(raffle.sponsorProceeds() + handler.ghostSponsorPaidOut(), raffle.grossSales() * 1500 / 10_000);
                assertEq(raffle.protocolFees() + handler.ghostProtocolPaidOut(), fee);
            }
        } else if (current == IRaffle.Status.NftWon && raffle.settlementComplete()) {
            assertEq(raffle.unsettledPot(), 0);
            assertEq(raffle.sponsorProceeds() + handler.ghostSponsorPaidOut(), raffle.grossSales() - fee);
            assertEq(raffle.protocolFees() + handler.ghostProtocolPaidOut(), fee);
        } else if (current == IRaffle.Status.Refunding) {
            assertEq(raffle.unsettledPot(), 0);
            assertEq(raffle.sponsorProceeds(), 0);
            assertEq(raffle.protocolFees(), 0);
            assertEq(raffle.remainingRefundLiability() + handler.ghostRefundPaidOut(), raffle.grossSales());
        }
    }

    function invariantPrizeCustodyMatchesClaimMarker() public view {
        if (raffle.prizeClaimed()) assertNotEq(prize.ownerOf(1), address(raffle));
        else assertEq(prize.ownerOf(1), address(raffle));
    }

    function invariantSettlementAndRedemptionMarkersMatchTicketState() public view {
        if (!raffle.settlementComplete()) {
            assertEq(raffle.winningTicketId(), 0);
            assertFalse(raffle.winnerRedeemed());
            return;
        }

        uint256 ticketId = raffle.winningTicketId();
        assertNotEq(ticketId, 0);
        assertEq(raffle.unsettledPot(), 0);
        if (raffle.winnerRedeemed()) {
            assertNotEq(raffle.winnerRecipient(), address(0));
            try raffle.ownerOf(ticketId) returns (address) {
                assertTrue(false, "redeemed winning ticket still exists");
            } catch { }
        } else {
            assertNotEq(raffle.ownerOf(ticketId), address(0));
            assertEq(raffle.winnerRecipient(), address(0));
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { Test } from "forge-std/Test.sol";

import { Raffle } from "../../../src/Raffle.sol";
import { RaffleFactory } from "../../../src/RaffleFactory.sol";
import { IRaffle } from "../../../src/interfaces/IRaffle.sol";
import { IRaffleFactory } from "../../../src/interfaces/IRaffleFactory.sol";
import { FalseERC20 } from "../../../src/mocks/FalseERC20.sol";
import { MockERC20 } from "../../../src/mocks/MockERC20.sol";
import { MockERC721 } from "../../../src/mocks/MockERC721.sol";
import { MockVRFV2PlusWrapper } from "../../../src/mocks/MockVRFV2PlusWrapper.sol";
import { ReentrantERC20 } from "../../../src/mocks/ReentrantERC20.sol";
import { ReentrantPrizeERC721 } from "../../../src/mocks/ReentrantPrizeERC721.sol";
import { ReentrantTicketReceiver } from "../../../src/mocks/ReentrantTicketReceiver.sol";

contract RaffleSecurityTest is Test {
    uint256 internal constant USDC = 1e6;
    bytes4 internal constant REENTRANCY_ERROR = bytes4(keccak256("ReentrancyGuardReentrantCall()"));

    address internal sponsor = makeAddr("security-sponsor");
    address internal buyer = makeAddr("security-buyer");
    address internal treasury = makeAddr("security-treasury");
    address internal outsider = makeAddr("security-outsider");

    MockERC20 internal quote;
    MockERC721 internal prize;
    MockVRFV2PlusWrapper internal vrfWrapper;
    RaffleFactory internal factory;
    uint256 internal nextPrizeId = 1;

    function setUp() public {
        vm.warp(1_000_000);
        quote = new MockERC20();
        prize = new MockERC721();
        vrfWrapper = new MockVRFV2PlusWrapper();
        factory = new RaffleFactory(address(quote), address(vrfWrapper), treasury);
        vm.prank(sponsor);
        prize.setApprovalForAll(address(factory), true);
        quote.mint(buyer, 1_000_000 * USDC);
        vm.deal(outsider, 100 ether);
    }

    function testReentrantReceiptReceiverCannotNestPurchase() public {
        Raffle raffle = _create(factory, address(prize), 10);
        ReentrantTicketReceiver receiver = new ReentrantTicketReceiver();
        receiver.configure(raffle, true);
        quote.mint(address(receiver), 2 * USDC);
        receiver.approveQuote(quote);

        receiver.buyTicket();

        assertTrue(receiver.reentryBlocked());
        assertEq(raffle.totalEntries(), 1);
        assertEq(raffle.ticketCount(), 1);
        assertEq(raffle.balanceOf(address(receiver)), 1);
        assertEq(raffle.grossSales(), USDC);
    }

    function testReentrantQuoteTokenCannotNestInboundPurchase() public {
        ReentrantERC20 hostile = new ReentrantERC20();
        RaffleFactory hostileFactory = _factoryWithQuote(address(hostile));
        vm.prank(sponsor);
        prize.setApprovalForAll(address(hostileFactory), true);
        Raffle raffle = _create(hostileFactory, address(prize), 2);

        hostile.mint(buyer, USDC);
        vm.prank(buyer);
        hostile.approve(address(raffle), USDC);
        hostile.arm(address(raffle));
        vm.prank(buyer);
        raffle.buyEntries(buyer, 1);

        assertTrue(hostile.reentryBlocked());
        assertEq(raffle.totalEntries(), 1);
        assertEq(hostile.balanceOf(address(raffle)), USDC);
    }

    function testReentrantQuoteTokenCannotNestWinnerWithdrawal() public {
        ReentrantERC20 hostile = new ReentrantERC20();
        RaffleFactory hostileFactory = _factoryWithQuote(address(hostile));
        vm.prank(sponsor);
        prize.setApprovalForAll(address(hostileFactory), true);
        Raffle raffle = _create(hostileFactory, address(prize), 2);

        hostile.mint(buyer, USDC);
        vm.prank(buyer);
        hostile.approve(address(raffle), USDC);
        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, 1);
        _resolve(raffle, 0);

        hostile.armOutbound(address(raffle));
        vm.prank(buyer);
        raffle.settleWinningTicket(receiptId);
        assertFalse(hostile.reentryBlocked());
        vm.prank(buyer);
        raffle.redeemWinningTicket(receiptId);
        assertTrue(hostile.reentryBlocked());
        assertEq(raffle.unsettledPot(), 0);
    }

    function testFalseReturningQuoteCannotCreateReceipt() public {
        FalseERC20 falseQuote = new FalseERC20();
        RaffleFactory falseFactory = new RaffleFactory(address(falseQuote), address(vrfWrapper), treasury);
        vm.prank(sponsor);
        prize.setApprovalForAll(address(falseFactory), true);
        Raffle falseRaffle = _create(falseFactory, address(prize), 1);
        falseQuote.mint(buyer, USDC);
        vm.prank(buyer);
        falseQuote.approve(address(falseRaffle), USDC);
        vm.prank(buyer);
        vm.expectRevert();
        falseRaffle.buyEntries(buyer, 1);
        assertEq(falseRaffle.totalEntries(), 0);
    }

    function testFalseReturningOutboundTransferRestoresClaimAndAccounting() public {
        ReentrantERC20 hostile = new ReentrantERC20();
        RaffleFactory hostileFactory = _factoryWithQuote(address(hostile));
        vm.prank(sponsor);
        prize.setApprovalForAll(address(hostileFactory), true);
        Raffle raffle = _create(hostileFactory, address(prize), 2);

        hostile.mint(buyer, USDC);
        vm.prank(buyer);
        hostile.approve(address(raffle), USDC);
        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, 1);
        _resolve(raffle, 0);
        raffle.settleWinningTicket(receiptId);

        uint256 treasuryClaim = raffle.protocolFees();
        hostile.setFailOutboundTransfer(true);
        vm.expectRevert();
        raffle.releaseProtocolFees();
        assertEq(raffle.protocolFees(), treasuryClaim);
        assertEq(raffle.accountedQuoteBalance(), USDC);

        hostile.setFailOutboundTransfer(false);
        assertEq(raffle.releaseProtocolFees(), treasuryClaim);
        assertEq(raffle.protocolFees(), 0);
        assertEq(hostile.balanceOf(treasury), treasuryClaim);
    }

    function testFalseReturningWinnerTransferRestoresTicketAndLazySettlement() public {
        ReentrantERC20 hostile = new ReentrantERC20();
        RaffleFactory hostileFactory = _factoryWithQuote(address(hostile));
        vm.prank(sponsor);
        prize.setApprovalForAll(address(hostileFactory), true);
        Raffle raffle = _create(hostileFactory, address(prize), 2);

        hostile.mint(buyer, USDC);
        vm.prank(buyer);
        hostile.approve(address(raffle), USDC);
        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, 1);
        _resolve(raffle, 0);

        hostile.setFailOutboundTransfer(true);
        vm.prank(buyer);
        vm.expectRevert();
        raffle.redeemWinningTicket(receiptId);
        assertEq(raffle.ownerOf(receiptId), buyer);
        assertFalse(raffle.winnerRedeemed());
        assertFalse(raffle.settlementComplete());
        assertEq(raffle.unsettledPot(), USDC);

        hostile.setFailOutboundTransfer(false);
        vm.prank(buyer);
        assertEq(raffle.redeemWinningTicket(receiptId), 800_000);
        assertEq(raffle.winnerProceeds(), 0);
        assertEq(hostile.balanceOf(buyer), 800_000);
    }

    function testFactoryReentrancyDuringPrizeEscrowIsBlockedAtomically() public {
        ReentrantPrizeERC721 hostilePrize = new ReentrantPrizeERC721();
        hostilePrize.mint(sponsor, 1);
        vm.prank(sponsor);
        hostilePrize.setApprovalForAll(address(factory), true);
        hostilePrize.arm(factory, 2);

        vm.prank(sponsor);
        Raffle raffle = Raffle(
            payable(factory.createRaffle(
                    IRaffleFactory.CreateRaffleParams({
                        sponsorRecipient: sponsor,
                        prizeToken: address(hostilePrize),
                        prizeTokenId: 1,
                        reserveEntries: 1,
                        endTime: uint64(block.timestamp + 1 days)
                    })
                ))
        );

        assertTrue(hostilePrize.reentryBlocked());
        assertEq(factory.raffleCount(), 1);
        assertEq(hostilePrize.ownerOf(1), address(raffle));
        assertEq(hostilePrize.ownerOf(2), address(hostilePrize));
    }

    function testPrizeCannotReenterDuringWinnerTransfer() public {
        ReentrantPrizeERC721 hostilePrize = new ReentrantPrizeERC721();
        uint256 tokenId = nextPrizeId;
        hostilePrize.mint(sponsor, tokenId);
        vm.prank(sponsor);
        hostilePrize.setApprovalForAll(address(factory), true);
        Raffle raffle = _create(factory, address(hostilePrize), 1);
        uint256 receiptId = _buy(raffle, 1);
        _resolve(raffle, 0);

        hostilePrize.armWinnerTransfer(IRaffle(address(raffle)), receiptId, buyer);
        vm.prank(outsider);
        raffle.settleWinningTicket(receiptId);
        assertEq(hostilePrize.reentryAttempts(), 0);
        vm.prank(buyer);
        raffle.redeemWinningTicket(receiptId);

        assertTrue(hostilePrize.reentryBlocked());
        assertEq(hostilePrize.reentryAttempts(), 1);
        assertEq(hostilePrize.reentryBlocks(), 1);
        assertEq(hostilePrize.reentrySelector(), REENTRANCY_ERROR);
        assertEq(hostilePrize.ownerOf(tokenId), buyer);
        assertTrue(raffle.prizeClaimed());
        assertEq(raffle.winningTicketId(), receiptId);
        assertEq(raffle.balanceOf(buyer), 0);
        assertEq(raffle.unsettledPot(), 0);
        assertEq(raffle.protocolFees(), 50_000);
        assertEq(raffle.sponsorProceeds(), 950_000);
        assertEq(raffle.accountedQuoteBalance(), USDC);
    }

    function testPrizeCannotReenterDuringSponsorSafeTransfer() public {
        ReentrantPrizeERC721 hostilePrize = new ReentrantPrizeERC721();
        uint256 tokenId = nextPrizeId;
        hostilePrize.mint(sponsor, tokenId);
        vm.prank(sponsor);
        hostilePrize.setApprovalForAll(address(factory), true);
        Raffle raffle = _create(factory, address(hostilePrize), 2);
        uint256 receiptId = _buy(raffle, 1);
        _resolve(raffle, 0);

        hostilePrize.armSponsorSafeTransfer(IRaffle(address(raffle)), receiptId, buyer);
        vm.prank(outsider);
        raffle.releaseSponsorPrize();

        assertTrue(hostilePrize.reentryBlocked());
        assertEq(hostilePrize.reentryAttempts(), 1);
        assertEq(hostilePrize.reentryBlocks(), 1);
        assertEq(hostilePrize.reentrySelector(), REENTRANCY_ERROR);
        assertEq(hostilePrize.ownerOf(tokenId), sponsor);
        assertTrue(raffle.prizeClaimed());
        assertEq(raffle.ownerOf(receiptId), buyer);
        assertEq(raffle.unsettledPot(), USDC);
        assertEq(raffle.protocolFees(), 0);
        assertEq(raffle.sponsorProceeds(), 0);
        assertEq(raffle.accountedQuoteBalance(), USDC);

        vm.prank(buyer);
        raffle.settleWinningTicket(receiptId);
        assertEq(raffle.unsettledPot(), 0);
        assertEq(raffle.accountedQuoteBalance(), USDC);
    }

    function testProtocolDestinationsCannotReceiveReceiptsOrPayouts() public {
        Raffle raffle = _create(factory, address(prize), 1);
        vm.prank(buyer);
        quote.approve(address(raffle), 2 * USDC);

        vm.prank(buyer);
        vm.expectRevert(abi.encodeWithSelector(IRaffle.UnsafeProtocolDestination.selector, address(factory)));
        raffle.buyEntries(address(factory), 1);
        assertEq(raffle.totalEntries(), 0);
        assertEq(quote.balanceOf(address(raffle)), 0);

        vm.prank(buyer);
        uint256 receiptId = raffle.buyEntries(buyer, 1);
        vm.prank(buyer);
        vm.expectRevert(abi.encodeWithSelector(IRaffle.UnsafeProtocolDestination.selector, address(raffle)));
        raffle.transferFrom(buyer, address(raffle), receiptId);

        _resolve(raffle, 0);
        vm.prank(outsider);
        raffle.settleWinningTicket(receiptId);
        vm.prank(buyer);
        raffle.redeemWinningTicket(receiptId);
        assertEq(prize.ownerOf(raffle.prizeTokenId()), buyer);
    }

    function testCallbackMakesNoQuoteOrPrizeExternalTransfers() public {
        Raffle nft = _create(factory, address(prize), 1);
        uint256 nftReceipt = _buy(nft, 1);
        uint256 quoteBefore = quote.balanceOf(address(nft));
        _resolve(nft, 0);
        assertEq(quote.balanceOf(address(nft)), quoteBefore);
        assertEq(prize.ownerOf(nft.prizeTokenId()), address(nft));
        assertEq(nft.ownerOf(nftReceipt), buyer);

        Raffle cash = _create(factory, address(prize), 2);
        uint256 cashReceipt = _buy(cash, 1);
        quoteBefore = quote.balanceOf(address(cash));
        _resolve(cash, 0);
        assertEq(quote.balanceOf(address(cash)), quoteBefore);
        assertEq(prize.ownerOf(cash.prizeTokenId()), address(cash));
        assertEq(cash.ownerOf(cashReceipt), buyer);
    }

    function _create(RaffleFactory selectedFactory, address prizeAddress, uint128 reserve)
        internal
        returns (Raffle raffle)
    {
        uint256 tokenId = nextPrizeId++;
        if (prizeAddress == address(prize)) prize.mint(sponsor, tokenId);
        vm.prank(sponsor);
        raffle = Raffle(
            payable(selectedFactory.createRaffle(
                    IRaffleFactory.CreateRaffleParams({
                        sponsorRecipient: sponsor,
                        prizeToken: prizeAddress,
                        prizeTokenId: tokenId,
                        reserveEntries: reserve,
                        endTime: uint64(block.timestamp + 1 days)
                    })
                ))
        );
    }

    function _factoryWithQuote(address selectedQuote) internal returns (RaffleFactory) {
        return new RaffleFactory(selectedQuote, address(vrfWrapper), treasury);
    }

    function _buy(Raffle raffle, uint128 entries) internal returns (uint256 receiptId) {
        vm.prank(buyer);
        quote.approve(address(raffle), type(uint256).max);
        vm.prank(buyer);
        receiptId = raffle.buyEntries(buyer, entries);
    }

    function _resolve(Raffle raffle, uint256 randomWord) internal {
        vm.warp(raffle.endTime());
        vm.prank(outsider);
        uint256 requestId = raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();
        vrfWrapper.fulfill(requestId, randomWord);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.36;

import { Test } from "forge-std/Test.sol";

import { Raffle } from "../../../src/Raffle.sol";
import { RaffleFactory } from "../../../src/RaffleFactory.sol";
import { IRaffle } from "../../../src/interfaces/IRaffle.sol";
import { IRaffleFactory } from "../../../src/interfaces/IRaffleFactory.sol";
import { AdversarialVRFV2PlusWrapper } from "../../../src/mocks/AdversarialVRFV2PlusWrapper.sol";
import { MockERC20 } from "../../../src/mocks/MockERC20.sol";
import { MockERC721 } from "../../../src/mocks/MockERC721.sol";

contract VrfAdversarialTest is Test {
    address internal sponsor = makeAddr("vrf-sponsor");
    address internal buyer = makeAddr("vrf-buyer");
    address internal treasury = makeAddr("vrf-treasury");

    MockERC20 internal quote;
    MockERC721 internal prize;
    AdversarialVRFV2PlusWrapper internal wrapper;
    RaffleFactory internal factory;
    uint256 internal nextPrizeId = 1;

    function setUp() public {
        vm.warp(100_000);
        quote = new MockERC20();
        prize = new MockERC721();
        wrapper = new AdversarialVRFV2PlusWrapper();
        factory = new RaffleFactory(address(quote), address(wrapper), treasury);
        vm.prank(sponsor);
        prize.setApprovalForAll(address(factory), true);
        quote.mint(buyer, 100 * 1e6);
        vm.deal(address(this), 100 ether);
    }

    function testFeeReadAndRequestFailuresRollBackToActiveThenRefundAtDeadline() public {
        Raffle raffle = _preparedRaffle();
        uint256 requestDeadline = raffle.drawRequestDeadline();
        vm.warp(requestDeadline - 1);

        wrapper.configureFailures(true, false, true, false);
        vm.expectRevert(AdversarialVRFV2PlusWrapper.FeeReadFailed.selector);
        raffle.requestDraw();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Active));
        assertEq(raffle.drawRequestedAt(), 0);

        wrapper.configureFailures(false, true, true, false);
        uint256 fee = wrapper.quotedFee();
        vm.expectRevert(AdversarialVRFV2PlusWrapper.RequestFailed.selector);
        raffle.requestDraw{ value: fee }();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Active));
        assertEq(raffle.drawRequestedAt(), 0);
        assertEq(raffle.vrfRequestId(), 0);

        vm.warp(requestDeadline);
        vm.expectRevert(
            abi.encodeWithSelector(IRaffle.DrawRequestWindowExpired.selector, requestDeadline, block.timestamp)
        );
        raffle.requestDraw{ value: fee }();

        raffle.enableRefunds();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Refunding));
        assertEq(raffle.unsettledPot(), 0);
        assertEq(raffle.remainingRefundLiability(), 1e6);
    }

    function testQuotedFeeCanChangeWithoutConsumingRequest() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        wrapper.configureFees(0, 1 ether);

        vm.expectRevert(abi.encodeWithSelector(AdversarialVRFV2PlusWrapper.InsufficientFee.selector, 1 ether, 0));
        raffle.requestDraw();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Active));

        wrapper.configureFees(1 ether, 1 ether);
        raffle.requestDraw{ value: 1 ether }();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Drawing));
        assertEq(wrapper.lastGasLimit(), 300_000);
        assertEq(wrapper.lastConfirmations(), 30);
        assertEq(wrapper.lastNumWords(), 1);
    }

    function testOfficialHelperCannotUseForcedNativeToSubsidizeQuoteDrift() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        wrapper.configureQuoteDrift(0.1 ether, 1 ether, 1 ether);
        vm.deal(address(raffle), 1 ether);

        vm.expectRevert(abi.encodeWithSelector(IRaffle.InsufficientVrfFee.selector, 1 ether, 0.1 ether));
        raffle.requestDraw{ value: 0.1 ether }();

        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Active));
        assertEq(address(raffle).balance, 1 ether);
        assertEq(wrapper.nextRequestId(), 0);
        assertEq(address(wrapper).balance, 0);
    }

    function testOfficialHelperRefundsAgainstActualLowerPrice() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        wrapper.configureQuoteDrift(1 ether, 0.4 ether, 0.4 ether);
        address requester = makeAddr("drift-requester");
        vm.deal(requester, 2 ether);
        uint256 balanceBefore = requester.balance;

        vm.prank(requester);
        raffle.requestDraw{ value: 1 ether }();

        assertEq(requester.balance, balanceBefore - 0.4 ether);
        assertEq(address(wrapper).balance, 0.4 ether);
        assertEq(address(raffle).balance, 0);
    }

    function testSynchronousWrongDuplicateAndValidCallbacksCannotResolveInFlightRequest() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        wrapper.configureSynchronousCallbacks(3, 0, 77, false);

        uint256 requestId = raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Drawing));
        assertEq(raffle.winningEntry(), 0);

        wrapper.fulfill(requestId, 0);
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.NftWon));
        assertEq(raffle.winningEntry(), 1);
        wrapper.fulfillAs(address(raffle), requestId + 1, 99);
        assertEq(raffle.winningEntry(), 1);
    }

    function testZeroRequestIdDoesNotMatchUntilRequestReturns() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        wrapper.configureRequestId(0, true);
        wrapper.configureSynchronousCallbacks(1, 0, 0, false);

        assertEq(raffle.requestDraw{ value: raffle.getVrfRequestPrice() }(), 0);
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Drawing));
        assertEq(raffle.winningEntry(), 0);

        wrapper.fulfillAs(address(raffle), 0, 0);
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.NftWon));
        assertEq(raffle.winningEntry(), 1);
    }

    function testRepeatedRequestIdsRemainRaffleScoped() public {
        Raffle first = _preparedRaffle();
        Raffle second = _preparedRaffle();
        wrapper.configureRequestId(7, true);
        vm.warp(first.endTime());

        assertEq(first.requestDraw{ value: first.getVrfRequestPrice() }(), 7);
        assertEq(second.requestDraw{ value: second.getVrfRequestPrice() }(), 7);
        wrapper.fulfillAs(address(first), 7, 0);
        assertEq(uint256(first.status()), uint256(IRaffle.Status.NftWon));
        assertEq(uint256(second.status()), uint256(IRaffle.Status.Drawing));
        wrapper.fulfillAs(address(second), 7, 0);
        assertEq(uint256(second.status()), uint256(IRaffle.Status.NftWon));
    }

    function testNonPersistedRequestStillHasBoundedFullRefundRecovery() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        wrapper.configureFailures(false, false, false, false);
        raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();

        vm.warp(raffle.callbackDeadline());
        raffle.enableRefunds();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Refunding));
        assertEq(raffle.remainingRefundLiability(), 1e6);
    }

    function testAuthenticatedValidCallbackAtDeadlineIsIgnoredBeforeRefunds() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        uint256 requestId = raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();

        vm.warp(raffle.callbackDeadline());
        wrapper.fulfill(requestId, 0);
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Drawing));
        assertEq(raffle.winningEntry(), 0);
        assertEq(raffle.resolvedAt(), 0);
        assertEq(raffle.unsettledPot(), 1e6);

        raffle.enableRefunds();
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Refunding));
        assertEq(raffle.unsettledPot(), 0);
        assertEq(raffle.remainingRefundLiability(), 1e6);
    }

    function testMalformedAndWrongCallbacksAreIgnoredUntilOneValidWordArrives() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        uint256 requestId = raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();

        wrapper.fulfillEmpty(address(raffle), requestId);
        wrapper.fulfillAs(address(raffle), requestId + 1, 0);
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Drawing));
        assertEq(raffle.winningEntry(), 0);

        wrapper.fulfillAs(address(raffle), requestId, 0);
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.NftWon));
        assertEq(raffle.winningEntry(), 1);
    }

    function testWrapperRequestReentryIsRejected() public {
        Raffle raffle = _preparedRaffle();
        vm.warp(raffle.endTime());
        wrapper.configureFailures(false, false, true, true);

        raffle.requestDraw{ value: raffle.getVrfRequestPrice() }();
        assertFalse(wrapper.lastReentrySucceeded());
        assertEq(uint256(raffle.status()), uint256(IRaffle.Status.Drawing));
    }

    function _preparedRaffle() internal returns (Raffle raffle) {
        uint256 tokenId = nextPrizeId++;
        prize.mint(sponsor, tokenId);
        vm.prank(sponsor);
        raffle = Raffle(
            payable(factory.createRaffle(
                    IRaffleFactory.CreateRaffleParams({
                        sponsorRecipient: sponsor,
                        prizeToken: address(prize),
                        prizeTokenId: tokenId,
                        reserveEntries: 1,
                        endTime: uint64(block.timestamp + 1 days)
                    })
                ))
        );
        vm.prank(buyer);
        quote.approve(address(raffle), 1e6);
        vm.prank(buyer);
        raffle.buyEntries(buyer, 1);
    }
}

